        omap[o] = n

# Now compute I (Item Class) for each row 6-607
# I = IFERROR(INDEX(N5:N271, MATCH(TRUE, EXACT(A, O5:O271), 0)), "")
# EXACT means exact string match

classes = {}
for r in range(6, 608):
    a = ws.cell(r, 1).value
    if a is not None and a in omap:
        classes[r] = omap[a]
    else:
        classes[r] = ''

# Check some values
for r in range(6, 20):
    print(r, repr(ws.cell(r,1).value), '->', repr(classes[r]))

# Check for duplicates in B within same class
from collections import defaultdict
class_items = defaultdict(list)
for r in range(6, 608):
    cls = classes[r]
    b = ws.cell(r, 2).value
    if cls and b is not None:
        class_items[cls].append((r, b))

# Find ties
